package com.example.acres.service; import com.example.acres.entity.*; import com.example.acres.repository.*; import org.springframework.stereotype.Service; import java.time.*; @Service public class AuditService {private final AuditLogRepository repo; public AuditService(AuditLogRepository r){repo=r;} public void log(User u,String action,String type,String id,String oldV,String newV,String ip){AuditLog a=new AuditLog();a.setUser(u);a.setAction(action);a.setEntityType(type);a.setEntityId(id);a.setOldValue(oldV);a.setNewValue(newV);a.setCreatedAt(Instant.now());a.setIpAddress(ip);repo.save(a);} }
